func shell(cfg *Config, maxRows, maxText, chunk int) *GPU {
	g := &GPU{
		cfg: cfg,
		H:   cfg.Hidden, inner: cfg.Inner(), ffn: cfg.FFN, heads: cfg.Heads, headDim: cfg.HeadDim,
		ropeHalf: cfg.RopeWidth() / 2,
		maxRows:  maxRows, maxText: maxText, chunk: chunk,
