	return NewGPUBank(dev, dir, maxRows, maxText, chunk, qwen.BankFP16)
}

// NewGPUBank is NewGPU with the block stack held as bank says: BankQ8 is
// ~22 GB of int8 banks and a 0.8 GB fp16 scratch in place of 40 GB.

