=== simQ8 test
	if s, ok := os.LookupEnv("H3_Q8_ARMS"); ok {
		arms = strings.Split(s, ";")
	}
	r := newRunRef(t)
	dev, done := newTestDevice(t)
	defer done()
	defer func() { simQ8 = nil }()
	for _, arm := range arms {
		simQ8 = map[proj]bool{}
		switch {
		case arm == "all":
			for _, p := range projOrder {
				simQ8[p] = true
			}
		case strings.HasPrefix(arm, "-"):
			for _, p := range projOrder {
				simQ8[p] = projNames[p] != arm[1:]
			}
		case arm != "":
			for _, name := range strings.Split(arm, ",") {
				for _, p := range projOrder {
					if projNames[p] == name {
						simQ8[p] = true
					}
				}
			}
		}
		g, err := NewGPU(dev, modelDir, 5120, 1024, 2048)
=== GPU fields
	aBias                   map[string]uint32
	actElems                int
	// hbuf (fp16): the q/k/v planes, the chunk A operands, the input rows.
	hQ, hK, hV, hA, hCtx, hFFN uint32
	hVid, hAud, hText          uint32
	hElems                     int

	// noKeyTail skips zeroKeyTail: TestGPUForward's negative control, and
	// nothing else.
	noKeyTail bool

	// Per-request state (Begin).
